102	export const failureOf = (error: unknown): Failure => {
103	  if (Predicate.isTagged(error, "Unauthenticated")) {
104	    return "Unauthenticated";
105	  }
106	
107	  if (Predicate.isTagged(error, "Forbidden")) {
108	    return "Forbidden";
109	  }
110	
111	  if (
112	    Predicate.isTagged(error, "TeamNotFound") ||
113	    Predicate.isTagged(error, "PersonNotFound") ||
114	    Predicate.isTagged(error, "PulseNotFound") ||
115	    Predicate.isTagged(error, "QuestionNotFound") ||
116	    Predicate.isTagged(error, "RoundNotFound") ||
117	    Predicate.isTagged(error, "ActionNotFound") ||
118	    Predicate.isTagged(error, "ResultsNotReady") ||
119	    Predicate.isTagged(error, "FailedEmailNotFound")
120	  ) {
121	    return "NotFound";
122	  }
123	
124	  if (Predicate.isTagged(error, "OwnerNotInTeam")) {
125	    return "Invalid";
126	  }
127	
128	  if (Predicate.isTagged(error, "LastLead")) {
129	    return "LastLead";
130	  }
131	
132	  if (Predicate.isTagged(error, "LastAdmin")) {
133	    return "LastAdmin";
134	  }
135	
136	  if (Predicate.isTagged(error, "ErasureNotConfirmed")) {
137	    return "ErasureNotConfirmed";
138	  }
139	
140	  if (Predicate.isTagged(error, "AccountStillInUse")) {
141	    return "AccountStillInUse";
142	  }
143	
144	  if (Predicate.isTagged(error, "TeamNameTaken")) {
145	    return "TeamNameTaken";
146	  }
147	
148	  for (const tag of [
149	    "QuestionAlreadyInPulse",
150	    "QuestionHasAnswers",
151	    "PulseNeedsAQuestion",
152	    "PulseFull",
153	    "OrderMismatch",
154	    "TestSendLimitReached",
155	    "EmailNotResendable",
156	  ] as const) {
157	    if (Predicate.isTagged(error, tag)) {
158	      return tag;
159	    }
160	  }
161	
162	  if (Predicate.isTagged(error, "HttpApiSchemaError") || Predicate.isTagged(error, "SchemaError")) {
163	    return "Invalid";
164	  }
165	
166	  return "Unavailable";
167	};
