169	export const clientEffect = HttpApiClient.make(SurveyBeatApi, {
170	  baseUrl: typeof window !== "undefined" ? window.location.origin : "http://localhost",
171	});
172	
173	export type ApiClient = Effect.Success<typeof clientEffect>;
174	
175	export const runApi = <A, M>(
176	  f: (api: ApiClient) => Effect.Effect<A, unknown>,
177	  onSuccess: (value: A) => M,
178	  onFailure: (failure: Failure) => M,
179	): Effect.Effect<M> => {
180	  const recover = (failure: unknown): Effect.Effect<M> => Effect.succeed(onFailure(failureOf(failure)));
181	
182	  return clientEffect.pipe(
183	    Effect.flatMap(f),
184	    Effect.map(onSuccess),
185	    Effect.catch(recover),
186	    Effect.provide(FetchHttpClient.layer),
187	  );
188	};
